window.EPI_CO.push({ id: "c_mabani_marefati", fa: "مبانی معرفتی", en: "Epistemic foundations", def: "پایه‌های نظری‌ای که اعتبار شناخت و ابزارهای آن را تضمین می‌کنند؛ پایداری باورهای دینی و حرکت‌های اجتماعی مستقیماً به استحکام آن‌ها وابسته است و انگیزه و شور اولیه بدون آن‌ها مانع انحراف نمی‌شود.", secs: ["s1", "s2"], vs: ["c_iman_taqlidi"], crit: "آیا باور یا حرکت، برای اعتبار ابزارهایی که بر آن‌ها تکیه دارد، دلیل معرفتی دارد یا فقط بر انگیزه، شعار یا تقلید تکیه دارد؟", conf: "گمان اینکه شور، انگیزه یا اقدام مدیریتی و شعاری جای پایه معرفتی را می‌گیرد.", ex: "سازمان مجاهدین خلق با انگیزه مذهبی آغاز کرد، اما به سبب فقدان پایه‌های معرفتی استوار اسلامی به التقاط با مارکسیسم، انشعاب و تروریسم رسید (جزوه s1).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_iman_taqlidi", fa: "ایمان تقلیدی", en: "Imitative (uncritical) faith", def: "ایمانی که بر تقلید و بدون ریشه عقلی استوار است و به تعبیر جزوه مانند گیاهی بی‌ریشه در برابر شبهات آسیب‌پذیر است.", secs: ["s1"], vs: ["c_mabani_marefati"], crit: "اگر از صاحب باور دلیل بخواهی، جز «همه می‌گویند» یا «این‌طور بزرگ شده‌ام» پاسخی دارد؟", conf: "یکی گرفتن استواری روانی باور با استواری معرفتی آن.", ex: "جزوه s1: ایمان متکی بر تقلید و بدون ریشه عقلی، در برابر شبهات مانند گیاهی بی‌ریشه آسیب‌پذیر است.", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_eltegat", fa: "التقاط", en: "Syncretism (eclectic mixing)", def: "درآمیختن مبانی فکری ناسازگار (در مثال جزوه: انگیزه مذهبی با مبانی مارکسیسم) که از نبودِ پایه‌های معرفتی استوار برمی‌خیزد و به انحراف فکری و تقابل‌های اجتماعی می‌انجامد.", secs: ["s1", "s2"], vs: ["c_mabani_marefati"], crit: "آیا اجزای یک منظومه فکری از مبانی معرفتی ناسازگار گرفته شده‌اند؟", conf: "گمان اینکه هر ترکیب از منابع گوناگون التقاط است؛ التقاط در اینجا درآمیختن مبانی ناسازگار است.", ex: "التقاط با مبانی مارکسیسم در سازمان مجاهدین خلق (جزوه s1).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_layers", fa: "لایه‌های بنیادین مواجهه با شبهه", en: "Layers of doubt", def: "سلسله‌مراتب سه‌لایه: روبنایی (عقاید: باورهای دینی و خداشناسی)، میانی (ابزارهای شناخت: اصل علیت، اعتبار ریاضی، استدلال عقلانی)، زیربنایی (معرفت‌شناسی: امکان شناخت، اعتبار حس و عقل، وجود جهان خارج)؛ پاسخ به لایه بالاتر متوقف بر حل لایه زیرین است.", secs: ["s2"], vs: [], crit: "اختلاف واقعی در کدام لایه است؟ اگر طرف بحث اعتبار ابزار را قبول ندارد، استدلال روبنایی بی‌اثر است.", conf: "بحث در لایه روبنایی در حالی که اختلاف اصلی در لایه میانی یا زیربنایی است.", ex: "طرفِ بحث گاه در کارایی عقل، اصل علیت، اعتبار ریاضی، داده‌های تجربی و حتی وجود جهان خارج یا خود تشکیک می‌کند؛ تا اعتبار این ابزارها اثبات نشود، استدلال خداشناسی بی‌اثر است (جزوه s2).", st: ["st_intake"] });
/* فصل ۲ */
window.EPI_CO.push({ id: "c_marefat", fa: "معرفت", en: "Knowledge / cognition (in the broad sense)", def: "در اصطلاح این مبحث، مطلقِ آگاهی و شناخت که هر نوع ادراک — جزئی، کلی، حسی، عقلی و عرفانی — را دربرمی‌گیرد؛ کاربرد لغوی و اصطلاحی آن در عربی، فارسی و انگلیسی با واژه‌هایی چون علم (Science/Knowledge) و شناخت تمایزهایی دارد.", secs: ["s4"], vs: ["c_jtb"], crit: "آیا با هر نوع آگاهی سروکار داریم؟ در این کارخانه آری؛ معرفت به معنای عام به کار می‌رود، نه فقط علم تجربی یا باور صادق موجه.", conf: "تنگ کردن «معرفت» به علم تجربی (Science) یا به معرفت به معنای خاص معرفت‌شناسی تحلیلی.", ex: "ادراک حسی درخت، مفهوم کلی انسان و مکاشفه عارف همه معرفت‌اند (جزوه s4).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_marefatshenasi", fa: "معرفت‌شناسی", en: "Epistemology", def: "دانشی که موضوعش خودِ شناخت و آگاهی انسان است و حقیقت، ساختار و ویژگی‌های آن را بررسی می‌کند؛ نقش آن سنجش میزان اعتبار و درستی ابزارهای تولید دانش است و پایه‌ای‌ترین دانش برای اثبات اعتبار سایر رشته‌هاست.", secs: ["s4", "s5", "s6"], vs: ["c_olum_digar"], crit: "آیا پرسش درباره خودِ شناخت و اعتبار ابزار آن است یا درباره پدیده‌ای از جهان؟", conf: "انتظار اینکه معرفت‌شناس درباره محتوای فیزیک یا تاریخ داوری کند؛ او درستیِ ابزار را می‌سنجد.", ex: "فیزیک‌دان از حس و تجربه، مورخ از اسناد، ریاضی‌دان از استدلال استفاده می‌کند؛ معرفت‌شناس می‌سنجد این ابزارها با چه تضمینی به واقعیت می‌رسانند (جزوه s5).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_olum_digar", fa: "علوم خاص (پیرامونی)", en: "First-order sciences", def: "علومی مانند فیزیک، شیمی، ریاضی و تاریخ که هر یک پدیده‌ها و موضوعات خاصی از جهان پیرامون را بررسی می‌کنند و دانشمندانشان مستقیماً از ابزارهای شناختی (حس، تجربه، عقل، اسناد) استفاده می‌کنند.", secs: ["s4", "s5", "s6"], vs: ["c_marefatshenasi"], crit: "آیا دانش، ابزار را به کار می‌برد (علم خاص) یا ابزار را می‌سنجد (معرفت‌شناسی)؟", conf: "یکی گرفتن «استفاده از ابزار» با «سنجش ابزار».", ex: "نمودار تقابل s5: سایر علوم، استفاده‌کننده از ابزارهای شناختی؛ معرفت‌شناسی، ارزیابی‌کننده و ناظر بر صحت آن‌ها.", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_bazres", fa: "تمثیل بازرس ابزارها", en: "Inspector-of-instruments analogy", def: "تمثیل جزوه برای رسالت معرفت‌شناس: در بازار علوم، هر دانشمند با ابزار ویژه خود دادوستد می‌کند؛ معرفت‌شناس مانند بازرس و ناظری است که درستیِ خودِ متر، ترازو و پیمانه را می‌سنجد.", secs: ["s5"], vs: [], crit: "آیا دارم درباره کالا (محتوا) داوری می‌کنم یا درباره ترازو (ابزار)؟", conf: "بازرس به‌جای سنجش ترازو، خودش وارد معامله شود.", ex: "حس، تجربه، عقل و نقل تاریخی با چه تضمینی و تا چه میزان ما را به واقعیت می‌رسانند؟ (جزوه s5).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_vaqenamayi", fa: "واقع‌نمایی", en: "Representing reality (veridicality)", def: "میزان انطباق و نمایش واقعیت توسط یک معرفت؛ ارزش معرفت در معرفت‌شناسی وابسته به آن است، همانند آینه‌ای که ارزشش به شفافیت و بازنمایی دقیق تصویر بدون کژی است.", secs: ["s6"], vs: ["c_sedq"], crit: "این آگاهی تا چه اندازه واقع را همان‌طور که هست نشان می‌دهد؟", conf: "سنجیدن ارزش معرفت با سودمندی، خوشایندی یا رواج آن به‌جای واقع‌نمایی.", ex: "تمثیل آینه (جزوه s6).", st: ["st_intake", "st_truth"] });
window.EPI_CO.push({ id: "c_daraje_etebar", fa: "درجات اعتبار معرفت", en: "Degrees of epistemic credibility", def: "طیف اعتبار معرفت از ظن و احتمال تا یقین مطلق؛ سنجش آن از حیاتی‌ترین مباحث است، چون خطای معرفتی در امور مربوط به سرنوشت و سعادت خسارت جبران‌ناپذیر دارد.", secs: ["s6"], vs: [], crit: "اطمینان به این آگاهی در کجای طیف احتمال تا یقین است و دلیلش چیست؟", conf: "دوارزشی دیدن معرفت (یا یقین یا هیچ) و نادیده گرفتن مراتب میانی.", ex: "جزوه s6: سنجش درجات اعتبار معرفت (از ظن و احتمال تا یقین مطلق).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_jtb", fa: "تحلیل سه‌جزئی معرفت (باور صادق موجه)", en: "Justified true belief (JTB) analysis", def: "تحلیلی در معرفت‌شناسی تحلیلی که خود جزوه در پانوشت فصل ۲ از دانشنامه فلسفه استنفورد نقل کرده: S می‌داند که P اگر و تنها اگر P صادق باشد، S به P باور داشته باشد و S در باور به P موجه باشد. متن جزوه این تحلیل را بحث نمی‌کند و «معرفت» را به معنای مطلق آگاهی به کار می‌برد.", secs: ["s6"], vs: ["c_marefat", "c_gettier"], crit: "آیا سخن از «معرفت» به معنای خاص (دانستن یک گزاره) است یا به معنای مطلق آگاهی؟", conf: "گمان اینکه تعریف جزوه از معرفت همان باور صادق موجه است.", ex: "پانوشت فصل ۲: Matthias Steup, «The Analysis of Knowledge», SEP.", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_gettier", fa: "مسئله گتیه", en: "Gettier problem", def: "به نقل پانوشت جزوه از دانشنامه اینترنتی فلسفه: موارد گتیه نشان می‌دهند ممکن است باوری صادق و موجه باشد اما معرفت نباشد؛ یعنی سه شرط تحلیل سه‌جزئی کافی نیست. متن جزوه این را بحث نمی‌کند.", secs: ["s6"], vs: ["c_jtb"], crit: "آیا باور صادق و موجه، از سر بخت (نه از راه پیوند درست توجیه با صدق) صادق شده است؟", conf: "گمان اینکه جزوه در متن به گتیه پاسخ داده است.", ex: "پانوشت فصل ۲: Stephen Hetherington, «Gettier Problems», IEP.", st: ["st_intake"] });
/* فصل ۳ */
window.EPI_CO.push({ id: "c_epi_aam", fa: "معرفت‌شناسی عام", en: "General epistemology", def: "شاخه‌ای که اعتبار هر نوع آگاهی و ابزارهای گوناگون شناخت (عقل، تجربه، حس، نقل) را بدون تمرکز بر موضوعی معین بررسی می‌کند؛ بنیادین و پیش‌نیاز ورود به همه شاخه‌های تخصصی است و حل مسائل بنیادین، تمایز علم حضوری و حصولی و نقد شک‌گرایی در آن جای دارد.", secs: ["s8", "s9"], vs: ["c_epi_khas"], crit: "آیا پرسش درباره اعتبار یک ابزار شناخت به‌طور کلی است، فارغ از موضوع؟", conf: "پریدن به داوری در یک حوزه خاص پیش از روشن شدن اعتبار عام ابزار.", ex: "آیا حس به‌طور کلی معتبر است؟ (جزوه s8).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_epi_khas", fa: "معرفت‌شناسی خاص", en: "Special (regional) epistemology", def: "شاخه‌ای که در چارچوب فلسفه‌های مضاف شکل می‌گیرد و اعتبار ابزارهای شناخت را در حوزه‌ای ویژه می‌سنجد — مانند اعتبار تجربه در علوم تجربی، گزاره‌ها در معرفت‌شناسی اخلاق، باورها در معرفت‌شناسی دین — و متوقف بر حل مباحث معرفت‌شناسی عام است.", secs: ["s8", "s9"], vs: ["c_epi_aam"], crit: "آیا سنجش، ابزارها را در قلمرو یک موضوع معین (دین، اخلاق، علم تجربی) به کار می‌گیرد؟", conf: "مستقل دانستن معرفت‌شناسی خاص از عام.", ex: "معرفت‌شناسی دین از ابزارهای عام شناخت بهره می‌برد، پس نتایج معتبرش متوقف بر حل مباحث عام است (جزوه s8).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_falsafe_mozaf", fa: "فلسفه مضاف", en: "Philosophy of X (second-order discipline)", def: "فلسفه‌ای که به یک حوزه معین افزوده (مضاف) می‌شود — مانند فلسفه دین، فلسفه اخلاق، فلسفه علم — و معرفت‌شناسی‌های خاص در چارچوب آن شکل می‌گیرند.", secs: ["s8"], vs: ["c_epi_aam"], crit: "آیا پرسش «فلسفه X» است، یعنی درباره مبانی و ابزارهای شناخت در حوزه X؟", conf: "یکی گرفتن فلسفه مضاف با خودِ آن علم (فلسفه دین با علم کلام یا فقه).", ex: "معرفت‌شناسی اخلاق، معرفت‌شناسی دین (جزوه s8).", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_epi_din", fa: "معرفت‌شناسی دین", en: "Epistemology of religion", def: "مصداق بارز معرفت‌شناسی خاص که میزان اعتبار و واقع‌نمایی گزاره‌های اعتقادی (هستی‌شناسانه) و مقررات عملی (بایدها و نبایدها) را بررسی می‌کند و سهم هر یک از راه‌های شناخت — عقل برهانی، شهود، حس، نقل، رجوع به متخصص — را در ساختار دین معین می‌کند؛ باورها، شبهات، تعدد قرائت‌ها و پلورالیسم را بر پایه مبانی عام بررسی می‌کند.", secs: ["s8", "s9"], vs: ["c_epi_aam"], crit: "آیا ادعا گزاره‌ای اعتقادی یا حکمی عملی در دین است و پرسش درباره اعتبار راه شناخت آن است؟", conf: "ورود به داوری درباره باورهای دینی بدون اجرای مسیر عام.", ex: "افزوده درس ۱۶ در s8.", st: ["st_intake"] });
window.EPI_CO.push({ id: "c_vaqeiyat", fa: "واقعیت (در معرفت‌شناسی)", en: "Reality (broad sense)", def: "مفهومی فراگیرتر از وجود خارجی که نه‌تنها اشیای مادی بلکه روابط منطقی، پیوندهای شرطی و حتی عدمِ یک شیء در یک موضع، و نیز حقایق ذهنی (کلیت مفهوم انسان)، حالات باطنی (شاد بودن) و روابط تلازم میان قضایا — حتی در شرطی‌های ممتنع و خلاف واقع — را دربرمی‌گیرد؛ از مفهوم وجود عام‌تر است.", secs: ["s9", "s38"], vs: ["c_nafsolamr"], crit: "آیا ادعا درباره چیزی است که مستقل از گفتن من، چنین هست یا نیست — حتی اگر مادی نباشد؟", conf: "یکی گرفتن واقعیت با وجود مادی و بیرون گذاشتن ادعاهای شرطی، عدمی و ذهنی از سنجش صدق.", ex: "«در این اتاق فیل نیست» درباره عدمِ یک شیء در یک موضع است که در گستره واقعیت قرار دارد (مثال ساخته سامانه بر پایه s9).", st: ["st_intake", "st_truth"] });
window.EPI_CO.push({ id: "c_nafsolamr", fa: "نفس‌الامر (واقعیت نفس‌الامری)", en: "Fact of the matter (nafs al-amr)", def: "ظرفِ ثبوتِ مفادِ هر قضیه به حسبِ خودش، که ملاکِ صدقِ تصدیق است: منحصر به امورِ مادی و خارجی نیست؛ حقایقِ ذهنی (مانندِ کلیتِ مفهومِ انسان)، حالاتِ باطنی (مانندِ شاد بودن) و روابطِ تلازم میانِ قضایا (حتی در شرطی‌های ممتنع و خلافِ واقع) همه مصداقِ آن‌اند (s38). صدقِ معرفت‌شناختی تطابقِ مفادِ گزاره با نفس‌الامر است.", secs: ["s6", "s38"], vs: ["c_vaqeiyat"], crit: "اگر این گزاره صادق باشد، چه چیزی — مادی، ذهنی، باطنی یا رابطهٔ تلازم — باید، قطع‌نظر از گفتنش، چنین باشد؟", conf: "محدود کردنِ نفس‌الامر به جهانِ مادی، و در نتیجه بی‌معنا دانستنِ صدقِ گزاره‌های ذهنی یا شرطیِ خلافِ واقع چون «در خارج چیزی متناظرشان نیست».", ex: "«مفهومِ انسان کلی است»، «من شادم»، و «اگر عددِ ۴ فرد بود، بر ۲ بخش‌پذیر نبود» — تلازم در شرطیِ ممتنع هم نفس‌الامر دارد (s38؛ مثالِ سوم ساختهٔ سامانه).", st: ["st_truth", "st_grade"], note: "ادغامِ دو تعریفِ هم‌شناسه (epi_st_a و epi_st_b، ۲۰۲۶-۱۰-۱۴، WORKLOG 42): هر دو از s38 بودند و تعارض نداشتند؛ تعریفِ ادغام‌شده لفظِ s38 را نگه می‌دارد و «ظرفِ ثبوت به حسبِ خودِ قضیه» همان تعبیرِ علامه مصباح در «آموزش فلسفه» است (برای قضایای منطقی ظرفِ ثبوتِ عقلی، برای خارجی ثبوتِ خارجی)." });
/* فصل ۴ */
window.EPI_CO.push({ id: "c_huzuri", fa: "علم حضوری", en: "Knowledge by presence (presential knowledge)", def: "علمی که در آن عین واقعیت معلوم بدون واسطه نزد عالم حاضر است؛ دورکنی (عالم و معلوم) و بدون هیچ مفهوم یا صورت واسطه.", secs: ["s11", "s12", "s13", "s14", "s18"], vs: ["c_husuli"], crit: "آیا خودِ معلوم نزد درک‌کننده حاضر است یا فقط تصویری از آن؟ اگر بتوان پرسید «آیا این تصویر با آن مطابق است؟»، حصولی است.", conf: "یکی گرفتن «خودم دیدم» (حضور عرفی) با علم حضوری؛ یا یکی گرفتن علت داشتن حالت با باواسطه بودن یافت آن.", ex: "آگاهی مستقیم هر فرد از شادی، ترس، امید یا درد خود (جزوه s11).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_husuli", fa: "علم حصولی", en: "Acquired (representational) knowledge", def: "علمی که در آن واقعیت شیء نزد عالم حاضر نیست و صورتی مفهومی از آن حاصل می‌شود؛ سه‌رکنی (عالم، معلوم، مفهوم واسطه)؛ بخش اعظم معارف بشری از این سنخ است و خطا تنها در آن راه دارد.", secs: ["s11", "s12", "s18", "s27"], vs: ["c_huzuri"], crit: "آیا میان من و معلوم صورتی ذهنی واسطه است که می‌تواند با آن مطابق باشد یا نباشد؟", conf: "گمان اینکه چون حس یا حضور فیزیکی در کار است، علم حضوری است.", ex: "پی بردن به اندوه یا شادی دیگری از چهره‌اش؛ دیدن درختی در جهان خارج (جزوه s11).", st: ["st_core", "st_tasdiq"] });
window.EPI_CO.push({ id: "c_arkan", fa: "ارکان علم (دورکنی و سه‌رکنی)", en: "Constituents of knowledge", def: "علم حصولی سه رکن دارد: عالم، معلوم و مفهوم واسطه — با فقدان مفهوم، ارتباط شناختی قطع می‌شود؛ علم حضوری دو رکن دارد: عالم و معلوم، بی‌هیچ واسطه مفهومی.", secs: ["s12"], vs: [], crit: "آیا می‌توان رکن سومی (صورت یا مفهوم) میان عالم و معلوم نشان داد؟", conf: "در s18 و نمودارش از «دو رکن واسطه و واقعیت» و «ساختار دومؤلفه‌ای علم حصولی» سخن رفته که مقصود دو طرف مطابقت (صورت و واقع) است، نه شمار ارکان.", ex: "در علم به شادی خودم: من و شادی؛ در دیدن درخت: من، درخت و صورت درخت.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_mafhum_vasete", fa: "مفهوم واسطه (صورت ذهنی)", en: "Mediating concept / mental representation", def: "صورت یا مفهومی که در علم حصولی میان عالم و معلوم واسطه می‌شود و آگاهی از طریق آن حاصل می‌شود؛ ملاک صدق و کذب مطابقت همین صورت با واقع است.", secs: ["s11", "s12", "s18", "s27"], vs: [], crit: "آیا چیزی هست که از معلوم حکایت کند و جای او در ذهن باشد؟", conf: "گمان اینکه مفهوم خودش معلوم است؛ مفهوم به‌عنوان پدیده درونی حضوری یافته می‌شود، اما به‌عنوان حکایت‌گر واسطه حصولی است (s36).", ex: "صورت درخت در ذهن (s11).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_bivasetegi", fa: "ملاک بی‌واسطگی", en: "Criterion of immediacy", def: "مقصود از بی‌واسطگی در علم حضوری نبودِ واسطه در فرایند خودِ درک و یافتن است، نه نفی علت پیدایش حالت.", secs: ["s12"], vs: [], crit: "آیا میان یابنده و خودِ حالت مفهومی واسطه است؟ (اینکه حالت علتی دارد ربطی ندارد.)", conf: "گمان اینکه چون ترس من از یک عامل بیرونی پدید آمده، علمم به ترس باواسطه است.", ex: "ترسیدن از یک عامل بیرونی: علت بیرونی است، اما یافتن ترس بی‌واسطه است (جزوه s12).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_huzur_orfi", fa: "حضور عرفی", en: "Ordinary (physical) presence", def: "حاضر بودن به معنای عرفی، مانند نشستن در کلاس درس؛ چون عین شیء به ذهن منتقل نمی‌شود، علم به آن از نظر فلسفی حصولی است.", secs: ["s12"], vs: ["c_huzuri"], crit: "آیا «حضور» فیزیکی است (من کنار شیء بودم) یا وجودی (خودِ معلوم نزد من است)؟", conf: "خطاناپذیر دانستن گواهی «خودم آنجا بودم».", ex: "نشستن در کلاس (جزوه s12).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_ilm_be_zat", fa: "علم به ذات خود", en: "Self-knowledge by presence", def: "نخستین قسم علم حضوری: علم انسان به خود، که در آن عالم و معلوم وحدت دارند؛ دائمی است؛ آنچه با آن درک می‌شود اصل وجود خویش است، نه چیستی و ویژگی‌های خود.", secs: ["s13", "s14", "s19"], vs: ["c_khata_chisti"], crit: "آیا ادعا فقط «من هستم» است، یا درباره چیستی و ویژگی‌های من؟", conf: "یکی گرفتن «خودم را می‌یابم» با «می‌دانم چه کسی/چه جور آدمی هستم».", ex: "پانوشت جزوه: روشن‌ترین مصداق علم حضوری خودآگاهی است و ابن‌سینا آن را پایه برهان «انسان معلق در فضا» قرار داد.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_halat_infeali", fa: "حالات انفعالی درونی", en: "Passive inner states", def: "دومین قسم علم حضوری: درک بی‌واسطه اموری که بر نفس عارض می‌شوند — غم، شادی، درد، (و در مثال‌های جزوه) ترس، امید، گرسنگی؛ انسان در آن‌ها فاعل نیست.", secs: ["s13", "s11", "s14"], vs: ["c_afal_ikhtiyari"], crit: "آیا این حالت بر من عارض شده (منفعلم) یا آن را انجام داده‌ام (فاعلم)؟", conf: "یکی گرفتن آن با افعال اختیاری؛ یا گمان اینکه چون علت دارد، حضوری نیست.", ex: "غم، شادی، درد (جزوه s13).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_afal_ikhtiyari", fa: "افعال اختیاری درونی", en: "Voluntary inner acts", def: "سومین قسم علم حضوری: شهود مستقیم تفکر، تصمیم‌گیری، اراده و نیت که با فاعلیت نفس رخ می‌دهند؛ تفاوتشان با حالات انفعالی در فاعل بودن انسان است، هرچند ادراک هر دو بی‌واسطه است.", secs: ["s13"], vs: ["c_halat_infeali"], crit: "آیا من کننده این فعل درونی‌ام؟", conf: "گمان اینکه علم به نیت خود حصولی و نیازمند استنتاج است.", ex: "تصمیم گرفتن، اراده کردن، نیت (جزوه s13).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_ilm_illat_maalul", fa: "علم علت هستی‌بخش به معلول و معلول به علت", en: "Presential knowledge between existential cause and effect", def: "چهارمین قسم علم حضوری (در فهرست s13): علم حضوری علت هستی‌بخش به معلول خود و شهود معلول نسبت به علت خویش؛ پایه علم حضوری انسان به خدا (فقر وجودی) است.", secs: ["s13", "s25"], vs: ["c_ilm_ehati"], crit: "آیا رابطه، رابطه هستی‌بخشی است (نه علیت طبیعی مانند آتش و گرما)؟", conf: "یکی گرفتن آن با علیت طبیعی یا با شناخت تفصیلی علت.", ex: "علم انسان به وابستگی وجودی‌اش به آفریننده (جزوه s25).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_ilm_be_mafahim", fa: "علم به مفاهیم ذهنی", en: "Presential knowledge of one's own concepts", def: "پنجمین قسم علم حضوری: علم عالم به خودِ صورت‌ها و مفاهیمی که در درونش پدید آمده و حاضرند.", secs: ["s13", "s36"], vs: ["c_mafhum_vasete"], crit: "آیا ادعا درباره داشتن یک مفهوم است («این تصور را دارم») یا درباره مطابقت آن با خارج؟", conf: "خلط «این مفهوم را دارم» (حضوری، قطعی) با «این مفهوم با واقع مطابق است» (حصولی).", ex: "هم‌اکنون مفهوم «دایره» در ذهن من حاضر است (s13؛ حیثیت دوگانه s36).", st: ["st_core", "st_ctype"] });
window.EPI_CO.push({ id: "c_daemi_mashrut", fa: "علم حضوری دائمی و مشروط", en: "Permanent vs. conditional presential knowledge", def: "برخی علوم حضوری دائمی‌اند (علم به خود) و برخی مشروط به پدید آمدن حالت (گرسنگی، ترس)؛ برخی اقسام ویژه مانند وحی یا مکاشفات به شرایط و افراد ویژه اختصاص دارند؛ انسان می‌تواند هم‌زمان چند ادراک حضوری و حصولی داشته باشد.", secs: ["s14"], vs: [], crit: "آیا این یافت همیشه هست یا فقط وقتی حالت پدید می‌آید؟", conf: "گمان اینکه چون یافتی همیشگی نیست، حضوری نیست.", ex: "احساس گرسنگی (مشروط) در برابر علم به خود (دائمی) (جزوه s14).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_mafhumsazi", fa: "مفهوم‌سازی تجارب حضوری", en: "Conceptualizing presential experience", def: "ذهن پیوسته یافته‌های حضوری را به مفاهیم حصولی تبدیل می‌کند تا بازخوانی، اندیشه و انتقال آن تجارب به دیگران ممکن شود؛ سپس از زبان برای نام‌گذاری و انتقال آن‌ها استفاده می‌کند.", secs: ["s14", "s16"], vs: [], crit: "آیا آنچه گزارش می‌کنم خودِ یافت است یا مفهومی که از آن ساخته‌ام؟", conf: "یکی گرفتن مفهوم ساخته‌شده از درد با خودِ درد — و سرایت دادن قطعیت یکی به دیگری.", ex: "گفتن «دردم می‌آید» به پزشک، که مفهوم و لفظ است نه خودِ درد (s14، s16).", st: ["st_core", "st_worlds"] });
/* فصل ۵ */
window.EPI_CO.push({ id: "c_alam_vaqe", fa: "عالم واقع", en: "Realm of reality", def: "ساحتی دربرگیرنده اموری که قطع نظر از آگاهی انسان وجود دارند؛ با فهم و زبان دگرگون نمی‌شود.", secs: ["s16"], vs: ["c_alam_fahm", "c_alam_zaban"], crit: "آیا اگر هیچ‌کس آن را نداند یا نگوید، همچنان چنین است؟", conf: "گذاشتن برداشت خود به‌جای واقع.", ex: "درختی در باغچه که بودنش به مشاهده انسان وابسته نیست (جزوه s16).", st: ["st_worlds", "st_truth"] });
window.EPI_CO.push({ id: "c_alam_fahm", fa: "عالم فهم (علم)", en: "Realm of understanding", def: "مرتبه شکل‌گیری صورت و درک در ذهن انسان پس از مواجهه با واقعیت؛ باید خود را با واقع منطبق سازد.", secs: ["s16"], vs: ["c_alam_vaqe", "c_alam_zaban"], crit: "آیا این، برداشت کسی است (و از آنِ چه کسی)؟", conf: "«فهمیدم، پس هست».", ex: "صورت درخت در ذهن پس از دیدن آن (s16).", st: ["st_worlds"] });
window.EPI_CO.push({ id: "c_alam_zaban", fa: "عالم زبان", en: "Realm of language", def: "مرتبه وضع الفاظ و نشانه‌های قراردادی برای تبادل فهم‌های ذهنی میان افراد در زیست اجتماعی؛ در ساحت حصولی و خطاپذیر جای دارد و باید با واقع منطبق شود.", secs: ["s16", "s22", "s19"], vs: ["c_alam_vaqe", "c_alam_fahm"], crit: "آیا با واژه و نشانه سروکار داریم — که قراردادی است و ممکن است معناهای گوناگون داشته باشد؟", conf: "گمان اینکه تغییر نام، واقع را تغییر می‌دهد؛ یا دانستن نام یعنی فهمیدن.", ex: "لفظ «درخت»؛ نام‌گذاری حالت ترس بر اساس آموزش (s16، s22).", st: ["st_worlds"] });
window.EPI_CO.push({ id: "c_khalt_avalem", fa: "خلط سه عالم", en: "Conflating reality, understanding and language", def: "یکی گرفتن واقع با فهم، یا فهم با زبان، یا نتیجه گرفتن تغییر واقع از تغییر فهم و زبان؛ به تصریح جزوه منشأ مغالطات فراوان است.", secs: ["s16"], vs: [], crit: "آیا جایی از «فهمیدم» به «هست»، از «نامش را می‌دانم» به «می‌فهمم» یا از «نامش عوض شد» به «خودش عوض شد» رسیده‌ام؟", conf: "گمان اینکه چون زبان و فهم ناگزیرند، پس واقع همان چیزی است که می‌فهمیم و می‌گوییم.", ex: "بازنام‌گذاری زیان به «هزینه یادگیری» و گمان اینکه زیانی رخ نداده (ساخته سامانه).", st: ["st_worlds"] });
window.EPI_CO.push({ id: "c_tashkik", fa: "مراتب تشکیکی علم حضوری", en: "Gradation of presential knowledge", def: "علم حضوری دوارزشی (صفر و یک) نیست، بلکه طیفی با شدت و ضعف است که از سه عامل برمی‌خیزد: مرتبه وجودی (سعه وجودی) عالم، درجه وجودی معلوم (درد شدید و خفیف)، و میزان توجه و تمرکز عالم به معلوم.", secs: ["s17", "s25"], vs: ["c_khatanapaziri"], crit: "شدت این یافت به کدام‌یک از سه عامل بسته است؟", conf: "یکی گرفتن ضعف یافت با خطای یافت؛ یا شدت یافت را دلیل درستی تفسیرش گرفتن.", ex: "درد شدید و خفیف (s17)؛ انصراف توجه موجب ضعف و تمرکز موجب شدت ادراک حضوری (s17) — مثلاً کم‌رنگ شدن درد هنگام اشتغال به کاری دیگر (نمونه ساخته سامانه).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_tavajjoh", fa: "توجه و التفات", en: "Attention", def: "سومین عامل شدت و ضعف علم حضوری: انصراف توجه موجب ضعف درک حضوری و تمرکز حواس موجب شدت آن می‌شود.", secs: ["s17"], vs: [], crit: "هنگام یافتن، توجهم کجا بود؟", conf: "گمان اینکه آنچه به آن توجه نکرده‌ام اصلاً نبوده است.", ex: "جزوه s17.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_khata", fa: "خطا (در معرفت‌شناسی)", en: "Error", def: "عدم مطابقت صورت ادراکی با واقعیت؛ این ملاک فقط در علم حصولی، که صورت واسطه و واقعیت دارد، جریان می‌یابد.", secs: ["s18"], vs: ["c_kezb"], crit: "آیا صورتی هست که بتواند با واقع مطابق نباشد؟", conf: "نسبت دادن خطا به خودِ احساس یا یافت.", ex: "تعیین ماهیت شیء دیده‌شده در غروب (s19).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_khatanapaziri", fa: "خطاناپذیری علم حضوری", en: "Infallibility of presential knowledge", def: "چون در علم حضوری خودِ واقعیت (به اتحاد یا حضور مستقیم) نزد درک‌کننده است و صورتی واسطه نیست، بحث مطابقت یا عدم مطابقت معنا ندارد؛ پس علم حضوری بالذات خطاناپذیر و دارای اعتبار مطلق معرفتی است.", secs: ["s18", "s19"], vs: ["c_khata"], crit: "آیا ادعا از حد هسته حضوری فراتر رفته است؟ اگر نه، خطاناپذیر است.", conf: "سرایت خطاناپذیری به تفسیر همراه؛ یا سرایت خطای تفسیر به هسته.", ex: "در درد فانتوم، اصل خارش یا درد حضوری و خطاناپذیر است (s19).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_salibe_entefa", fa: "سالبه به انتفای موضوع", en: "Negation by absence of subject", def: "قضیه سلبی‌ای که صدقش از نبودِ موضوع است؛ در نمودار s18: «عدم مطابقت صورت با خارج» در علم حضوری سالبه به انتفای موضوع است، چون صورتی نیست تا مطابق نباشد.", secs: ["s18"], vs: [], crit: "آیا نفی به این سبب صادق است که موضوعِ حکم اصلاً وجود ندارد؟", conf: "گمان اینکه خطاناپذیری حضوری یعنی «مطابقتِ کامل»؛ در واقع مطابقت و عدم مطابقت هر دو موضوعاً منتفی‌اند.", ex: "«صورتِ ادراکیِ درد من با درد مطابق نیست» — سالبه به انتفای موضوع (نمودار s18).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_shobahat_huzuri", fa: "سه حوزه شبهه خطا در علم حضوری", en: "Three alleged domains of presential error", def: "شبهاتی که درباره وقوع خطا در علم حضوری مطرح شده در سه حوزه است: علم به چیستی خود، ادراک حالات درونی (احساسات و بیماری‌ها)، و آگاهی از مبدأ هستی.", secs: ["s18"], vs: [], crit: "شبهه در کدام حوزه است و پاسخش کدام بخش (s19، s21–s25) است؟", conf: "گمان اینکه وجود این شبهات خطاناپذیری را نقض می‌کند؛ پاسخ جزوه این است که در هر سه حوزه خطا در تفسیر حصولی همراه است.", ex: "شیء نامتعین در غروب (چیستی)، درد فانتوم (حالات)، تطبیق فقر بر مصداق باطل (مبدأ).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_khata_chisti", fa: "خطا در چیستی (علم به خود)", en: "Error about what something is", def: "در شبهه علم به خود، آنچه حضوری درک می‌شود صرفاً اصل وجود خویش است؛ تعیین چیستی (چه هستم) ادراکی حصولی و محتمل‌الخطاست — مانند دیدن شیء نامتعین در تاریکی غروب که اصل دیدن صائب است ولی تعیین ماهیتش حصولی است.", secs: ["s19"], vs: ["c_ilm_be_zat"], crit: "آیا ادعا «هست» را می‌گوید یا «چیست» را؟", conf: "یکی گرفتن یافت اصل وجود با شناخت چیستی.", ex: "شیء در غروب (s19).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_estedlal_naakhodagah", fa: "استدلال ناخودآگاه حصولی", en: "Unconscious inference", def: "استنتاج‌هایی که ذهن بدون آگاهی ما و بر اساس تعمیم‌های تجربی گذشته بر یافت حضوری سوار می‌کند و علت یا موضع احساس را داوری می‌کند؛ خطا در همین‌جا رخ می‌دهد.", secs: ["s19", "s21"], vs: [], crit: "کدام سابقه یا عادت ذهنی مرا از «احساس» به «علت/محل» رسانده است؟", conf: "تجربه کردن نتیجه استدلال ناخودآگاه به‌عنوان بخشی از خودِ احساس.", ex: "داوری «معده خالی است» از احساس گرسنگی کاذب (s19).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_gorsnegi_kazeb", fa: "گرسنگی کاذب", en: "False hunger", def: "مثال جزوه: احساس گرسنگی خودش واقعیتی وجدانی و حضوری است، اما ذهن به خطا علت آن را خالی بودن معده داوری می‌کند.", secs: ["s19"], vs: [], crit: "آیا «گرسنه‌ام» (حضوری) از «معده‌ام خالی است» (حصولی) جدا شده است؟", conf: "گمان اینکه چون علت خطا بود، خودِ احساس «کاذب» بود.", ex: "پانوشت جزوه: کلیولند کلینیک درباره پلی‌فاژی — خوردن معمولاً آن را برطرف نمی‌کند جز در افت قند خون.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_khoresh_dard", fa: "اشتباه میان خارش و درد", en: "Itch/pain confusion", def: "مثال جزوه در s19: در اشتباه میان خارش و درد نیز خودِ احساس و پیام دریافتی حضوری و خطاناپذیر است و خطا در لایه حصولی رخ می‌دهد. جزوه جزء خطادار را در این مثال جداگانه نام نمی‌برد؛ اینکه خطا در مفهوم‌سازی و دسته‌بندی احساس به‌عنوان «خارش» یا «درد» است، تطبیق سامانه از قاعده عام s19 است.", secs: ["s19"], vs: [], crit: "آیا اشتباه در یافتن است یا در مفهوم و نامی که بر آن گذاشته شد؟", conf: "«اشتباه کردم، پس احساسم غلط بود»؛ در حالی که فقط دسته‌بندی و نام آن خطا بود.", ex: "جزوه s19.", st: ["st_core"] });
