window.EPI_CO.push({ id: "c_andam_khiyali", fa: "اندام خیالی (درد فانتوم)", en: "Phantom limb", def: "احساس خارش یا درد در عضو قطع‌شده (مثلاً انگشت پای غایب)؛ تحریک مسیر عصبی یا بازآرایی نقشه قشر مغز همان پیام حسی را بازسازی می‌کند و ذهن بر اساس سابقه و به روش حصولی به اشتباه منشأ را عضو غایب می‌پندارد. اصل احساس حضوری و خطاناپذیر است؛ انتساب به عضو، حصولی و خطا.", secs: ["s19", "s21"], vs: ["c_dard_erjai"], crit: "آیا «احساسی هست» از «در فلان عضو است» جدا شده؟", conf: "گمان اینکه درد فانتوم «درد خیالی» یعنی غیرواقعی است؛ خودِ درد واقعی است.", ex: "پانوشت‌ها: کلیولند کلینیک (بیش از نیمی از قطع‌عضوشدگان)، StatPearls (تصاحب نواحی قشر حسی و حرکتی توسط نواحی مجاور).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_dard_erjai", fa: "درد ارجاعی", en: "Referred pain", def: "دردی که به سبب اشتراک مسیرهای عصبی در جایی جز منشأ واقعی حس می‌شود؛ مانند التهاب آپاندیس که درد ابتدا اطراف ناف حس می‌شود و سپس به محل اصلی بازمی‌گردد.", secs: ["s21"], vs: ["c_andam_khiyali"], crit: "آیا محل احساس با محل منشأ یکی فرض شده است؟", conf: "قطعی دانستن محل درد چون خودِ درد قطعی است.", ex: "آپاندیس (جزوه s21؛ پانوشت StatPearls: تحریک فیبرهای آوران احشایی T8–T10).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_tafsir_hessi", fa: "تفسیر حصولی احساس بدنی", en: "Interpretation of bodily sensation", def: "تعیین منشأ فیزیکی، محل دقیق یا علت درد که حاصل استدلال و تفسیر ذهنی است و خطا در همین بخش رخ می‌دهد؛ آگاهی از وضعیت بافت و جراحت نیز حصولی است، پس آرام شدن درد به معنای التیام نیست.", secs: ["s21"], vs: ["c_khatanapaziri"], crit: "آیا ادعا درباره احساس است یا درباره بدن و بافت؟", conf: "«دیگر درد ندارم، پس خوب شده‌ام».", ex: "جزوه s21.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_markaz_agahi", fa: "تمرکز آگاهی در نفس", en: "Locus of awareness", def: "به تعبیر s22، آگاهی انسان در نفس یا مغز متمرکز است و عضو بیرونی فاقد ادراک مستقل است — به همین سبب احساس در عضو غایب ممکن است.", secs: ["s22"], vs: [], crit: "آیا گمان کرده‌ام خودِ عضو «حس می‌کند»؟", conf: "گمان اینکه خودِ عضو بیرونی حس می‌کند و بنابراین بدون عضو احساس ممکن نیست.", ex: "جزوه s22.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_barchasb", fa: "برچسب‌گذاری زبانی حالات درونی", en: "Linguistic labelling of inner states", def: "در حالات روانی مانند ترس یا وسواس، اصل پدیدار حضوری است، اما اینکه حالت از خطر واقعی است یا توهم، و نام‌گذاری آن بر اساس قرارداد زبانی و آموزش، ساحتی حصولی دارد.", secs: ["s22"], vs: ["c_halat_infeali"], crit: "آیا سه چیز — حالت، نام، داوری درباره خاستگاه — جدا شده‌اند؟", conf: "نام آموخته‌شده یا احساس را دلیل وجود خطر بیرونی گرفتن.", ex: "ترس و وسواس (جزوه s22).", st: ["st_worlds", "st_core"] });
window.EPI_CO.push({ id: "c_mokashefe", fa: "مکاشفه عرفانی", en: "Mystical unveiling (kashf)", def: "پرده‌برداری از حقایقی که در شرایط عادی بر عامه پنهان است و از راه صفای باطن و ریاضت حاصل می‌شود؛ شامل شهود صور یا شنیدن اصوات باطنی؛ اصل دریافت خطاناپذیر و تعبیر و تفسیر و تعیین منشأ حصولی و خطاپذیر است.", secs: ["s22", "s23", "s14"], vs: ["c_tabir"], crit: "آیا اصل دیدن یا شنیدن از تعبیر و منشأیابی آن جدا شده است؟", conf: "حجت دانستن تعبیر به اعتبار قطعیت اصل دریافت.", ex: "شنیدن ندا در باطن (s23).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_tabir", fa: "تعبیر و تأویل مکاشفه", en: "Interpretation of an unveiling", def: "آنچه ذهن عارف به اصل رؤیت یا سماع می‌افزاید؛ به تصریح ابن‌عربی در فتوحات مکیه، خطا نه در اصل رؤیت یا سماع بلکه در همین تعبیر و تأویل است.", secs: ["s23"], vs: ["c_mokashefe"], crit: "کدام بخش گزارش، «دیدم/شنیدم» است و کدام «یعنی…»؟", conf: "یکی گرفتن «دیدم/شنیدم» با «یعنی…» و سرایت قطعیت اولی به دومی.", ex: "حسن بصری در جنگ جمل در تطبیق و استنباط معنای ندا لغزید (s23).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_manshae_mokashefe", fa: "منشأهای چهارگانه مکاشفه", en: "Four possible sources of unveiling", def: "منشأ مکاشفه می‌تواند الهی، ملکی، نفسانی یا شیطانی باشد؛ تعیین آن حصولی است.", secs: ["s23"], vs: [], crit: "آیا منشأ بی‌دلیل الهی فرض شده است؟", conf: "الهی دانستن هر تجربه باطنی.", ex: "ندای شیطانی که حسن بصری شنید (s23).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_meyar_mokashefe", fa: "معیار سنجش مکاشفه", en: "Criterion for judging unveilings", def: "اگر مکاشفه‌ای با کشف معصوم یا موازین قطعی عقل و وحی ناسازگار باشد، خطای تفسیری یا شیطانی تلقی می‌شود.", secs: ["s23", "s25"], vs: [], crit: "آیا تعبیر با کشف معصوم و موازین قطعی عقل و وحی سازگار است؟", conf: "سنجیدن مکاشفه با مکاشفه‌ای دیگر یا با اعتبار شخص مکاشف.", ex: "جزوه s23.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_kashf_masum", fa: "کشف معصوم", en: "Unveiling of the infallible", def: "مکاشفه پیامبر یا امام معصوم که در جزوه یکی از معیارهای سنجش مکاشفات دیگران است.", secs: ["s23"], vs: [], crit: "آیا مکاشفه ادعایی با آنچه از کشف معصوم رسیده سازگار است؟", conf: "سنجیدن مکاشفه با شهرت یا کرامت مکاشف به‌جای سنجش با کشف معصوم.", ex: "جزوه s23.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_ilqa", fa: "القائات شیطانی و نفسانی", en: "Satanic or egoic suggestions", def: "دخالت شیطان یا نفس در مکاشفه که منشأ خطای آن است؛ در کنار تفسیرها و تعبیرهای حصولی، یکی از دو منشأ خطای مکاشفه است.", secs: ["s23"], vs: [], crit: "آیا محتوای مکاشفه با موازین قطعی عقل و وحی ناسازگار است؟", conf: "گمان اینکه هر صدا یا صورت باطنی، چون باطنی است، منشأ الهی دارد.", ex: "ندای شیطانی در ماجرای حسن بصری (s23).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_khata_enekasi", fa: "خطای انعکاسی", en: "Reflective (projective) error", def: "لغزشگاهی در مکاشفه که شخص احوال، رذایل یا آلودگی‌های درونی خود را در آینه باطن پاک دیگران می‌بیند و به اشتباه آن را به مخاطب نسبت می‌دهد.", secs: ["s24"], vs: [], crit: "آیا مکاشفه حکمی درباره باطن دیگری است که ممکن است بازتاب حال خود مکاشف باشد؟", conf: "معتبر دانستن داوری اهل شهود درباره باطن دیگران.", ex: "نقل ابن‌عربی درباره برخی رجبیون؛ کسی که باطن برزخی دیگران را حیوانی می‌دید و سپس خود را در همان هیئت یافت (s24).", st: ["st_core"] });
window.EPI_CO.push({ id: "c_safaye_baten", fa: "مراتب صفای باطن", en: "Degrees of inner purity", def: "صفای باطن درجات و مراتب متعدد دارد؛ پس دستیابی به مرتبه‌ای از شهود به معنای نیل به کمال نهایی نیست.", secs: ["s24"], vs: [], crit: "آیا از «او شهود دارد» نتیجه گرفته‌ام «او کامل یا مصون از خطاست»؟", conf: "گمان اینکه هر صاحب شهودی به کمال نهایی رسیده و از خطا مصون است.", ex: "جزوه s24.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_faqr_vojudi", fa: "فقر وجودی (علم حضوری به خدا)", en: "Existential poverty / dependence", def: "علم حضوری انسان به خدای متعال برآمده از عین فقر، ربط و تعلق وجودی معلول به علت است؛ هستی انسان جز وابستگی به آفریننده نیست و اصل این نیاز را همگان، حتی منکران، حضوری درمی‌یابند.", secs: ["s25"], vs: ["c_ilm_ehati"], crit: "آیا ادعا فقط اصل نیاز و وابستگی است یا توصیف و تطبیق آن؟", conf: "از یافت اصل نیاز، درستی تصویر خاصی از خدا را نتیجه گرفتن.", ex: "جزوه s25.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_ilm_ehati", fa: "علم احاطی", en: "Encompassing knowledge", def: "علمی که معلوم را به تمامی دربرگیرد؛ علم حضوری انسان به خدا احاطی نیست، چون گنجایش شهودی هر موجود به اندازه سعه وجودی اوست و انسان متناهی است؛ پس شناخت تفصیلی ذات و صفات نیازمند عقل، وحی و مفاهیم حصولی است.", secs: ["s25", "s17"], vs: ["c_faqr_vojudi"], crit: "آیا ادعا مدعی شناخت ذات یا جمیع صفات است؟", conf: "از یافت حضوری اصل نیاز به مبدأ، شناخت کامل ذات و صفات را نتیجه گرفتن.", ex: "جزوه s25.", st: ["st_core"] });
window.EPI_CO.push({ id: "c_tatbiq", fa: "خطای تطبیق حصولی", en: "Error of application", def: "لغزشی که نه در درک اصل (مثلاً فقر وجودی) بلکه در تطبیق حصولی آن بر مصادیق (چه بسا باطل) رخ می‌دهد.", secs: ["s25"], vs: [], crit: "آیا یافتی درست را بر مصداقی نادرست منطبق کرده‌ام؟", conf: "گمان اینکه چون اصل یافت درست است، هر مصداقی که بر آن تطبیق کرده‌ام هم درست است.", ex: "تطبیق نیاز فطری به مبدأ بر معبودهای باطل (s25).", st: ["st_core"] });
/* فصل ۷ */
window.EPI_CO.push({ id: "c_tasavvor", fa: "تصور", en: "Conception", def: "صرف پدید آمدن معنا یا صورت در ذهن بدون هیچ حکم، قضاوت، نفی یا اثبات درباره هستی و نیستی آن؛ متصف به صدق و کذب نمی‌شود. مفاهیم منفرد، ترکیب‌های اضافی، جمله‌های انشایی و پرسشی از این قبیل‌اند.", secs: ["s27", "s28", "s38"], vs: ["c_tasdiq"], crit: "آیا چیزی برای چیزی اثبات یا نفی شده است؟ اگر نه، تصور است.", conf: "صادق یا کاذب دانستن یک مفهوم، ترکیب وصفی یا دستور.", ex: "«کوه»، «کتابِ علی»، «باران ببار!»، «آیا باران می‌بارد؟».", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tasdiq", fa: "تصدیق", en: "Assent / judgment", def: "قضاوت و حکم درباره واقعیت — اثبات یا نفی یک ویژگی برای شیء — که در قالب جمله خبری بیان می‌شود، قابلیت صدق و کذب دارد و لزوماً به معنای یقین نیست، بلکه احکام احتمالی را هم دربرمی‌گیرد.", secs: ["s27", "s28", "s38"], vs: ["c_tasavvor"], crit: "آیا جمله خبری است و چیزی را برای چیزی اثبات یا نفی می‌کند (هرچند احتمالی)؟", conf: "یکی گرفتن تصدیق با یقین.", ex: "«امروز باران می‌بارد»، «احتمالاً فردا باران می‌بارد».", st: ["st_tasdiq", "st_truth"] });
window.EPI_CO.push({ id: "c_tarkib_ezafi", fa: "ترکیب اضافی (و وصفی)", en: "Incomplete (attributive) compound", def: "ترکیبی از مفاهیم که در آن حکمی صادر نشده (مضاف و مضاف‌الیه، موصوف و صفت)؛ جزوه آن را از مصادیق تصور می‌شمارد.", secs: ["s27"], vs: ["c_tasdiq"], crit: "آیا می‌توان پرسید «راست است یا دروغ؟» — اگر نه، تصور است.", conf: "«استراتژی سودآور» را حکم به سودآوری گرفتن.", ex: "«کتابِ علی»، «بازار پرنوسان».", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_jomle_inshai", fa: "جمله انشایی", en: "Performative / non-declarative sentence", def: "جمله‌ای که از واقعیت خبر نمی‌دهد (امر، نهی، آرزو، پرسش و مانند آن) و به همین سبب متصف به صدق و کذب نمی‌شود.", secs: ["s27", "s38"], vs: ["c_jomle_khabari"], crit: "آیا جمله چیزی را گزارش می‌کند یا چیزی را می‌خواهد/می‌پرسد؟", conf: "گفتن «این دستور غلط است» به معنای کذب.", ex: "«بخرید!»، «کاش باران ببارد».", st: ["st_tasdiq", "st_truth"] });
window.EPI_CO.push({ id: "c_jomle_khabari", fa: "جمله خبری", en: "Declarative sentence", def: "قالب بیان تصدیق: جمله‌ای که از واقعیت خبر می‌دهد و پذیرای صدق و کذب است.", secs: ["s27"], vs: ["c_jomle_inshai"], crit: "آیا می‌توان گفت «راست گفت/دروغ گفت»؟", conf: "گمان اینکه هر جمله خبری لزوماً یقینی است؛ خبر احتمالی هم خبر است.", ex: "«کل از جزء بزرگ‌تر است».", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_badihi", fa: "بدیهی", en: "Self-evident", def: "ادراکی (تصور یا تصدیق) که بی‌نیاز از فرایند اکتساب — تعریف یا استدلال — حاصل است.", secs: ["s28"], vs: ["c_nazari"], crit: "آیا برای داشتن آن به تعریف یا استدلال نیاز است؟", conf: "یکی گرفتن «بدیهی» با «آشنا» یا «مشهور».", ex: "تصور غم و شادی؛ تصدیق بی‌نیاز از استدلال.", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_nazari", fa: "نظری", en: "Acquired by reasoning (non-self-evident)", def: "ادراکی که از راه اکتساب حاصل می‌شود: تصور نظری با تعریف، تصدیق نظری با استدلال.", secs: ["s28"], vs: ["c_badihi"], crit: "آیا برای داشتنش باید از معلومات پیشین گذر کرد؟", conf: "گمان اینکه «نظری» یعنی «حدسی» یا «غیرواقعی»؛ نظری یعنی نیازمند اکتساب.", ex: "تصور دایره؛ نتیجه یک برهان.", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tasavvor_badihi", fa: "تصور بدیهی", en: "Self-evident concept", def: "مفهوم پایه‌ای که بی‌واسطه از راه حس یا علم حضوری به دست می‌آید و نیازی به ترکیب مفاهیم پیشین ندارد.", secs: ["s28"], vs: ["c_tasavvor_nazari"], crit: "آیا مفهوم مستقیماً از حس یا یافت درونی گرفته شده و تعریف‌پذیر به مفاهیم روشن‌تر نیست؟", conf: "گمان اینکه چون نمی‌توان مفهومی را تعریف کرد، مبهم است؛ تصور بدیهی بی‌نیاز از تعریف است.", ex: "ادراک حالات درونی غم و شادی (s28).", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tasavvor_nazari", fa: "تصور نظری", en: "Defined (acquired) concept", def: "مفهومی که از ترکیب و تحلیل تصورات پیشین پدید می‌آید؛ این فرایند «تعریف» است و تصور نظری از طریق تعریف به تصور بدیهی بازمی‌گردد.", secs: ["s28"], vs: ["c_tasavvor_badihi"], crit: "آیا برای روشن شدن، باید با مفاهیم دیگر تعریفش کرد؟", conf: "داوری با مفهوم نظری مبهم بی‌آنکه تعریفش روشن شود.", ex: "دایره با خط، منحنی و مرکز (s28).", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tasdiq_badihi", fa: "تصدیق بدیهی", en: "Self-evident judgment", def: "حکمی که مستقیماً و بدون نیاز به استدلال پذیرفته می‌شود؛ تصدیق‌های نظری از طریق استدلال بر آن بنا می‌شوند. (اقسام آن — اولیات و وجدانیات — در ایستگاه st_badihi.)", secs: ["s28"], vs: ["c_tasdiq_nazari"], crit: "آیا پذیرشش به هیچ تصدیق دیگری تکیه ندارد؟", conf: "بدیهی دانستن حکمی صرفاً چون برای من آشنا یا مورد اتفاق جمع است.", ex: "«من شادم» یا «کل از جزء بزرگ‌تر است» (نمونه‌ها از s39).", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tasdiq_nazari", fa: "تصدیق نظری", en: "Inferred judgment", def: "حکمی که از مسیر پیوند دادن تصدیق‌های معلوم برای کشف حکم جدید حاصل می‌شود؛ این فرایند «استدلال» یا «استنتاج» است.", secs: ["s28"], vs: ["c_tasdiq_badihi"], crit: "آیا پذیرشش به تصدیق‌های دیگر تکیه دارد؟", conf: "گمان اینکه تصدیق نظری چون استدلالی است، لزوماً قطعی یا لزوماً ظنی است؛ اعتبارش به ماده و صورت استدلال بسته است (سالن ۳).", ex: "نتیجه یک قیاس.", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_tarif", fa: "تعریف", en: "Definition", def: "فرایند ترکیب و تحلیل تصورات پیشین برای پدید آوردن تصور نظری.", secs: ["s28"], vs: ["c_estedlal"], crit: "آیا هدف روشن کردن یک مفهوم است (نه اثبات یک حکم)؟", conf: "یکی گرفتن تعریف با استدلال.", ex: "تعریف دایره (s28).", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_estedlal", fa: "استدلال (استنتاج)", en: "Inference / argument", def: "فرایند پیوند دادن تصدیق‌های معلوم برای کشف تصدیق جدید (نظری).", secs: ["s28"], vs: ["c_tarif"], crit: "آیا از حکم‌هایی به حکمی دیگر رسیده‌ایم؟", conf: "یکی گرفتن استدلال با تعریف؛ استدلال حکم می‌سازد، تعریف مفهوم را روشن می‌کند.", ex: "از «هر انسانی فانی است» و «سقراط انسان است» به «سقراط فانی است» (ساخته سامانه).", st: ["st_tasdiq"] });
window.EPI_CO.push({ id: "c_aqsam_chaharganeh", fa: "اقسام چهارگانه علم حصولی", en: "Fourfold division of acquired knowledge", def: "از تلاقی دو تقسیم (تصور/تصدیق و بدیهی/نظری) چهار قسم پدید می‌آید: تصور بدیهی، تصور نظری، تصدیق بدیهی، تصدیق نظری.", secs: ["s28"], vs: [], crit: "اول بپرس حکم هست یا نه؛ سپس بپرس نیاز به اکتساب (تعریف/استدلال) هست یا نه.", conf: "خلط دو تقسیم: بدیهی/نظری را با تصور/تصدیق یکی گرفتن.", ex: "نمودار درختی فصل ۷.", st: ["st_tasdiq"] });
/* فصل ۸ */
window.EPI_CO.push({ id: "c_jozi", fa: "تصور جزئی", en: "Particular concept", def: "ادراکی که بر یک مصداق یا شیء معین صدق می‌کند و امکان اشتراک ندارد؛ متناظر با اسم خاص در زبان.", secs: ["s30", "s31"], vs: ["c_kolli"], crit: "آیا ذهن می‌تواند آن را بر بیش از یک مورد منطبق کند؟ اگر نه، جزئی است.", conf: "جزئی دانستن مفهومی که فقط یک مصداق موجود دارد (خورشید).", ex: "دماوند (s30).", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_kolli", fa: "تصور کلی (معقول)", en: "Universal concept", def: "مفهومی که بر بیش از یک مورد قابل‌انطباق است؛ ملاک کلیت قابلیت ذهنی صدق بر کثیر است نه تعداد مصادیق خارجی؛ «معقول» نامیده می‌شود چون عقل آن را انتزاع می‌کند؛ به تمامی بر تک‌تک مصادیقش صدق می‌کند.", secs: ["s30", "s33"], vs: ["c_jozi", "c_kol"], crit: "آیا فرض مصادیق متعدد در ذهن ممکن است؟", conf: "سنجیدن کلیت با شمار مصادیق؛ یا یکی گرفتن کلی با کل.", ex: "کوه؛ خورشید، دایناسور، واجب‌الوجود، شریک‌الباری (s30).", st: ["st_partial", "st_ctype"] });
window.EPI_CO.push({ id: "c_kol", fa: "کل (در برابر جزء)", en: "Whole (vs. part)", def: "مجموعه‌ای که از اجزا ساخته شده و بر هر جزء به‌تنهایی اطلاق نمی‌شود؛ برخلاف مفهوم کلی که بر تک‌تک مصادیقش صدق می‌کند.", secs: ["s30"], vs: ["c_kolli"], crit: "آیا عنوان بر تک‌تک اجزا هم صدق می‌کند؟ اگر نه، کل است نه کلی.", conf: "نسبت دادن حکم کل به جزء (مغالطه کل و جزء).", ex: "به دست انسان، انسان گفته نمی‌شود (s30).", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_moghalate_kol_jozv", fa: "مغالطه جزء و کل", en: "Part–whole fallacy", def: "خلط نسبت کل و جزء با نسبت کلی و جزئی: حکم کل را به اجزا (یا در تعمیم سامانه، حکم اجزا را به کل) سرایت دادن.", secs: ["s30"], vs: [], crit: "آیا حکمی که درباره مجموعه است به عضو نسبت داده شده (یا برعکس)؟", conf: "گمان اینکه هر حکمی که درباره «همه» گفته می‌شود به تک‌تک افراد سرایت می‌کند، بی‌آنکه معلوم شود «همه» به معنای کلی است یا به معنای مجموعه.", ex: "«سبد سودده است، پس هر استراتژی‌اش سودده است» (ساخته سامانه).", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_tasavvor_hessi", fa: "تصور حسی", en: "Sensory perception", def: "مرتبه نخست تصور جزئی که از راه حواس پنج‌گانه شکل می‌گیرد و بقای آن مشروط به برقراری ارتباط حسی با موضوع خارجی است.", secs: ["s31"], vs: ["c_tasavvor_khiyali"], crit: "آیا ارتباط حسی با شیء اکنون برقرار است؟", conf: "یکی گرفتن یادآوری با ادراک حسی حاضر.", ex: "دیدن دماوند هنگام نگاه کردن به آن.", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_tasavvor_khiyali", fa: "تصور خیالی", en: "Imaginal (retained) image", def: "صورت جزئی‌ای که پس از قطع ارتباط حسی در ذهن باقی می‌ماند.", secs: ["s31"], vs: ["c_tasavvor_hessi", "c_takhayyol"], crit: "آیا شیء دیگر در برابر حواس نیست و صورتش از حافظه می‌آید؟", conf: "یکی گرفتن آن با ادراک حسی حاضر؛ یا با محصول تخیل.", ex: "به یاد آوردن چهره دوستی که رفته است.", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_quve_khiyal", fa: "قوه خیال", en: "Retentive imagination", def: "قوه‌ای که وظیفه نگهداری (بایگانی) و بازخوانی صورت‌های حسی را پس از قطع ارتباط با خارج بر عهده دارد.", secs: ["s31"], vs: ["c_takhayyol"], crit: "آیا کارِ قوه نگهداری و بازآوردن است، نه ساختن؟", conf: "یکی گرفتن خیال (نگهداری) با تخیل (ساختن).", ex: "جزوه s31.", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_takhayyol", fa: "قوه تخیل", en: "Creative imagination", def: "قوه‌ای فراتر از خیال که صورت‌های خیالی ذخیره‌شده را تجزیه و ترکیب می‌کند و صورت‌های نوین ذهنی می‌آفریند؛ محصولاتش لزوماً مابازاء خارجی ندارند اما بستر اصلی خلاقیت هنری، طراحی و نوآوری‌اند.", secs: ["s31"], vs: ["c_quve_khiyal"], crit: "آیا این صورت از ترکیب یا تجزیه صورت‌های دیگر ساخته شده است؟", conf: "گزارش واقع دانستن محصول تخیل؛ یا بی‌ارزش دانستن آن.", ex: "اسب بالدار از ترکیب صورت اسب و پرنده (s31).", st: ["st_partial"] });
window.EPI_CO.push({ id: "c_mabazaa", fa: "مابازاء خارجی", en: "External correlate", def: "مصداق یا ما به ازایی که در جهان خارج با صورت یا مفهوم مطابق است؛ محصولات تخیل لزوماً آن را ندارند و مفاهیم منطقی مصداق مستقیم خارجی ندارند.", secs: ["s31", "s34", "s35"], vs: [], crit: "آیا در خارج چیزی هست که این صورت/مفهوم بر آن منطبق شود؟", conf: "از داشتن تصویر روشن، وجود مابازاء را نتیجه گرفتن.", ex: "اسب بالدار (s31).", st: ["st_partial", "st_ctype"] });
/* فصل ۹ */
window.EPI_CO.push({ id: "c_mahuvi", fa: "مفهوم ماهوی (معقول اول)", en: "Quidditative concept (primary intelligible)", def: "مفهوم کلی‌ای که از تجرید ادراک حسی جزئی — رها کردن خصوصیات جزئی، زمانی و مکانی — پدید می‌آید و چیستی، ذات و حدود وجودی موجودات خارجی را بیان می‌کند؛ در پاسخ «این چیست؟» به کار می‌رود.", secs: ["s33", "s36"], vs: ["c_falsafi", "c_manteqi"], crit: "گام ۲ الگوریتم: آیا بر امر واقعی اطلاق می‌شود و چیستی آن را می‌گوید؟", conf: "انتظار اینکه همه مفاهیم ماهوی باشند (خطای هیوم به تعبیر جزوه).", ex: "انسان، درخت، سنگ، گل، حیوان، سبز (s33).", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_tajrid", fa: "تجرید (انتزاع)", en: "Abstraction", def: "فرایندی که ذهن با رها کردن خصوصیات جزئی، زمانی و مکانی یک صورت حسی، از آن مفهوم کلی می‌سازد.", secs: ["s33", "s30"], vs: [], crit: "آیا مفهوم از یک ادراک جزئی با حذف ویژگی‌های فردی به دست آمده است؟", conf: "گمان اینکه مفهوم کلی همان تصویر مبهم یک فرد است؛ تجرید یعنی رها کردن خصوصیات جزئی، زمانی و مکانی.", ex: "از سبزی یک برگ معین به مفهوم سبز (s33).", st: ["st_ctype", "st_partial"] });
window.EPI_CO.push({ id: "c_falsafi", fa: "مفهوم فلسفی (معقول ثانی فلسفی)", en: "Philosophical secondary intelligible", def: "مفهومی که از مقایسه روابط میان موجودات و تحلیل ذهنی پدیده‌ها به دست می‌آید، چیستی شیء را نشان نمی‌دهد اما بر امور واقعی و خارجی انطباق دارد (عروض در ذهن، اتصاف در خارج، بی‌مابازاء مستقل حسی).", secs: ["s34", "s36"], vs: ["c_mahuvi", "c_manteqi"], crit: "گام ۲ الگوریتم: بر امر واقعی اطلاق می‌شود اما حاصل مقایسه و تحلیل روابط است.", conf: "انکار آن چون حس نمی‌شود؛ یا موجود مستقل پنداشتن آن.", ex: "علت و معلول (آتش و گرما)، وجود و عدم، ضرورت و امکان، قوه و فعل، ثبات و تغییر، وحدت و کثرت، عدد (s34).", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_orooz_ettesaf", fa: "عروض ذهنی و اتصاف خارجی", en: "Mental occurrence, external predication", def: "تعبیر نمودار فصل ۹ برای ویژگی مفاهیم فلسفی: در ذهن عارض می‌شوند (ساخته تحلیل ذهن‌اند) اما اشیای خارجی به آن‌ها متصف می‌شوند (آتش در خارج واقعاً علت است)، بی‌آنکه مابه‌ازای مستقل حسی داشته باشند.", secs: ["s34"], vs: [], crit: "آیا شیء خارجی واقعاً به این وصف متصف است، هرچند خودِ وصف مابازاء مستقل ندارد؟", conf: "از ذهنی بودن عروض، غیرواقعی بودن اتصاف را نتیجه گرفتن.", ex: "«آتش علت است» (s34).", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_etebari_aqlani", fa: "مفاهیم فلسفی و اعتباری-عقلانی حقوق و اخلاق", en: "Rational-conventional normative concepts", def: "به تعبیر جزوه، در حقوق و اخلاق مفاهیمی مانند عدالت، ظلم، حق، مالکیت، و باید و نباید مفاهیمی فلسفی و اعتباری-عقلانی‌اند که برای سامان‌دهی رفتارها در مسیر کمال انسانی یا تنظیم روابط اجتماعی وضع شده‌اند.", secs: ["s34"], vs: ["c_mahuvi"], crit: "آیا مفهوم، رابطه‌ای هنجاری یا حقوقی را می‌گوید (نه چیستی شیء)؟", conf: "ماهوی دانستن مالکیت (گویی ویژگی فیزیکی ملک است) یا بی‌ارتباط با واقع دانستن عدالت.", ex: "مالکیت ملک وثیقه (ساخته سامانه بر پایه s34).", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_manteqi", fa: "مفهوم منطقی (معقول ثانی منطقی)", en: "Logical secondary intelligible", def: "مفهومی که صرفاً بر مفاهیم و موجودات ذهنی اطلاق می‌شود و هیچ مصداق مستقیمی در خارج ندارد؛ همواره عارض و وصف مفهوم ذهنی دیگری است و ویژگی‌های شناختی و حکایت‌گری مفاهیم را تبیین می‌کند.", secs: ["s35", "s36"], vs: ["c_mahuvi", "c_falsafi"], crit: "گام ۱ الگوریتم: آیا وصف امری ذهنی است؟", conf: "صفت شیء خارجی دانستن آن («این شخص کلی است»).", ex: "تصور، تصدیق، بدیهی، نظری، کلی، جزئی؛ انسان خارجی نه کلی است نه جزئی (s35).", st: ["st_ctype", "st_tasdiq"] });
window.EPI_CO.push({ id: "c_heysiat_dogane", fa: "حیثیت دوگانه مفاهیم (تمثیل آینه)", en: "Dual aspect of concepts", def: "مفاهیم ذهنی مانند آینه‌اند: از یک سو خود پدیده‌ای درونی در نفس‌اند که با علم حضوری ادراک می‌شوند، و از سوی دیگر حکایت‌گر واقعیات بیرونی‌اند که واسطه علم حصولی قرار می‌گیرند.", secs: ["s36"], vs: [], crit: "آیا سخن از «داشتن مفهوم» (حضوری) است یا از «درستی حکایتش» (حصولی)؟", conf: "سرایت قطعیتِ داشتن مفهوم به درستی حکایت آن.", ex: "جزوه s36.", st: ["st_ctype", "st_core"] });
window.EPI_CO.push({ id: "c_algorithm", fa: "الگوریتم دومرحله‌ای تشخیص مفاهیم", en: "Two-step classification test", def: "۱) آیا مفهوم وصف امور ذهنی است؟ اگر آری، منطقی است. ۲) اگر بر امور واقعی اطلاق می‌شود، آیا چیستی و ذات شیء را بیان می‌کند (ماهوی) یا حاصل مقایسه و تحلیل ذهنی روابط است (فلسفی)؟", secs: ["s36"], vs: [], crit: "برای هر مفهوم کلی: ابتدا گام ۱، سپس در صورت لزوم گام ۲.", conf: "شروع از گام ۲ پیش از گام ۱.", ex: "«علت»: گام ۱ خیر، گام ۲ رابطه ← فلسفی.", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_tajrobegerayi", fa: "تجربه‌گرایی (لغزش)", en: "Empiricism (as the booklet's warning)", def: "جزوه (s36) می‌گوید تفکیک سه‌گانه مفاهیم مانع «لغزش‌های تجربه‌گرایی و ایدئالیسم» است و در همان بند خطای هیوم را می‌آورد: او با تصور اینکه همه مفاهیم باید حسی و ماهوی باشند، چون علیت را نتوانست مستقیماً حس کند، ضرورت علّی را انکار و به عادت ذهنی تقلیل داد. تطبیق صریح «لغزش تجربه‌گرایی» بر همین خطا برداشت سامانه از کنار هم آمدن این دو در متن است.", secs: ["s36"], vs: ["c_idealism"], crit: "آیا از حس‌نشدن یک مفهوم، غیرواقعی بودنش نتیجه گرفته شده است؟", conf: "انکار هر مفهومی که حس نمی‌شود — علیت، ضرورت، عدالت — به این دلیل که با حواس ادراک نمی‌شود.", ex: "هیوم و علیت (s36).", st: ["st_ctype"] });
window.EPI_CO.push({ id: "c_idealism", fa: "ایدئالیسم (لغزش)", en: "Idealism (as the booklet's warning)", def: "جزوه (s36) از «لغزش ایدئالیسم» در کنار تجربه‌گرایی نام می‌برد و در همان بند می‌گوید کانت در پاسخ به هیوم علیت را قالبی پیشینی در ذهن دانست و به شکاکیت نوینی رسید. تطبیق «لغزش ایدئالیسم» بر این راه، و توضیح آن به اینکه مفهوم فلسفی صرفاً ساخت ذهن گرفته شود و حکایتش از خارج از دست برود، برداشت سامانه است.", secs: ["s36"], vs: ["c_tajrobegerayi"], crit: "آیا مفهوم فلسفی صرفاً ساخت ذهن و بی‌دلالت بر خارج گرفته شده است؟", conf: "گمان اینکه چون مفهوم فلسفی ساخته تحلیل ذهن است، از واقع حکایت نمی‌کند.", ex: "کانت و علیت (s36).", st: ["st_ctype"] });
/* s38 */
window.EPI_CO.push({ id: "c_sedq", fa: "صدق (معرفت‌شناختی)", en: "Truth (epistemic)", def: "مطابقت فهم (مفاد تصدیق) با واقعیت نفس‌الامری، فارغ از نیت و باور گوینده؛ فقط در قلمرو تصدیقات مطرح است.", secs: ["s38", "s6"], vs: ["c_sedq_akhlaqi", "c_kezb"], crit: "آیا آنچه گزاره می‌گوید با نفس‌الامر مطابق است؟", conf: "داوری صدق از روی صداقت یا نیت گوینده.", ex: "شهادت زبانی منافقان به رسالت پیامبر از نظر واقعیت صادق بود (s38).", st: ["st_truth"] });
window.EPI_CO.push({ id: "c_kezb", fa: "کذب (معرفت‌شناختی)", en: "Falsity", def: "عدمِ مطابقتِ فهم (مفادِ تصدیق) با نفس‌الامر (s38)؛ در مقیاسِ درجهٔ اعتبار، «کذبِ یقینی» معادلِ صفر است (s40) — ولی تصدیقی که به بدیهیات نرسیده لزوماً کاذب نیست، ظنی است.", secs: ["s38", "s40"], vs: ["c_sedq", "c_sedq_marefat"], crit: "آیا مفادِ تصدیق با نفس‌الامر ناسازگار است؟ اگر این ناسازگاری یقینی است، درجه صفر است؛ اگر نه، درجه‌اش را بسنج، نه این‌که کاذبش بدانی.", conf: "(۱) یکی گرفتنِ کذب با دروغ (کذبِ اخلاقی): کسی که صادقانه در خطاست، کاذب به معنای معرفتی گفته اما دروغ نگفته است. (۲) کاذب دانستنِ هر تصدیقی که به بدیهیات نرسیده؛ چنین تصدیقی ظنی است نه لزوماً کاذب.", ex: "«در این حساب هیچ تراکنشِ مشکوکی نیست» در حالی که یکی هست (ساختهٔ سامانه)؛ «چوبِ درونِ آب واقعاً شکسته است» پس از کنترلِ شرایط کاذب است.", st: ["st_truth", "st_grade"], note: "ادغامِ دو تعریفِ هم‌شناسه (۲۰۲۶-۱۰-۱۴، WORKLOG 42): هر دو از s38 بودند، دومی s40 را هم داشت؛ هیچ بخشی دور ریخته نشد." });
window.EPI_CO.push({ id: "c_sedq_akhlaqi", fa: "صدق اخلاقی", en: "Truthfulness (moral) / sincerity", def: "مطابقتِ گفتارِ شخص با باور و اعتقادِ قلبیِ او؛ با صدقِ معرفت‌شناختی (مطابقتِ مفاد با نفس‌الامر) متفاوت است (s38).", secs: ["s38", "s6"], vs: ["c_sedq", "c_sedq_marefat"], crit: "آیا پرسش این است که «گوینده آنچه را باور دارد گفت؟» (نه این‌که آیا گفته‌اش با واقع مطابق است)؟", conf: "از صداقتِ گوینده صدقِ گفته را نتیجه گرفتن (گوینده می‌تواند صادقانه خطا کند)، یا از دروغگویی‌اش کذبِ گفته را.", ex: "شهادتِ منافقان به رسالتِ پیامبر: از حیثِ واقعیت صادق، از حیثِ اخلاقی به سببِ فقدانِ باورِ درونی کذب (s38؛ منافقون/۱: «والله یشهد إنّ المنافقین لکاذبون»).", st: ["st_truth", "st_grade", "st_naql"], note: "ادغامِ دو تعریفِ هم‌شناسه (۲۰۲۶-۱۰-۱۴، WORKLOG 42). همان تمایزِ صدقِ خبری/مخبری در علمِ اصول و بلاغت: قولِ مشهور صدقِ خبر را مطابقت با واقع می‌داند و قولِ نظّام (مطابقت با اعتقادِ گوینده) را رد می‌کند — این‌جا آن معنا «صدقِ اخلاقی» نام دارد، نه صدقِ خبر." });
window.EPI_CO.push({ id: "c_talazom", fa: "روابط تلازم میان قضایا", en: "Entailment relations", def: "پیوند لزومی میان قضایا که خود مصداق واقعیت نفس‌الامری است، حتی در قضایای شرطی ممتنع و خلاف واقع.", secs: ["s38", "s9"], vs: [], crit: "آیا ادعا درباره لزوم یک قضیه از قضیه دیگر است؟", conf: "خارج دانستن شرطی‌های خلاف واقع از صدق و کذب.", ex: "«اگر حد ضرر گذاشته بودم، حسابم نمی‌سوخت» (ساخته سامانه).", st: ["st_truth"] });
window.EPI_CO.push({ id: "c_tawjih", fa: "توجیه", en: "Justification", def: "اقامه دلیل و تبیین وجه صدق یک تصدیق، تا اعتبار معرفتی آن اثبات شود. (سنجش تفصیلی آن در سالن داوری.)", secs: ["s38"], vs: ["c_sedq"], crit: "آیا برای این تصدیق دلیلی ارائه شده که نشان دهد چرا صادق است؟", conf: "یکی گرفتن توجیه‌شدن با صادق‌بودن.", ex: "برای تصدیق «بر این ملک رهنی ثبت نشده»، ارائه استعلام رسمی مرجع ثبت به‌عنوان دلیل (ساخته سامانه).", st: ["st_truth"] });

